'use strict';
let profileDraft=null,profileStep=1,profileIdentity=null,returnToSummary=false;
const preferenceLabels={vegetarian:'Без мяса',no_fish:'Без рыбы',no_milk:'Без молочных продуктов'};
const activityChoices=[[1.2,'Низкая','Сидячий день, мало движения'],[1.375,'Лёгкая','Прогулки, 1-3 тренировки в неделю'],[1.55,'Средняя','3-5 тренировок в неделю'],[1.725,'Высокая','Активная работа или частые тренировки']];
const goalLabels={lose:'Похудение',maintain:'Поддержание',gain:'Набор'};
const flowPages=new Set(['dashboard','profile','onboarding','settings','result','menu','shopping','baskets']);
function draftKey(){return 'fitnutrition:onboarding:'+session.email;}
function profileIsSaved(){return state?.profile_complete===true;}
function prepareDraft(){
 if(profileIdentity===session.email&&profileDraft)return;
 profileIdentity=session.email;const p=state.profile||{};
 profileDraft={name:p.name||session.email.split('@')[0],sex:p.sex||null,birth_date:p.birth_date||null,age:p.age??null,weight:p.weight??null,height:p.height??null,activity:p.activity??null,goal:p.goal||null,allergens:p.allergens||[],preferences:p.preferences||[],other_allergies:p.other_allergies||'',other_enabled:!!p.other_allergies,budget_week:p.budget_week??null};
 profileStep=1;
 try{const saved=JSON.parse(localStorage.getItem(draftKey())||'null');if(saved?.draft&&typeof saved.draft==='object'){for(const key of Object.keys(profileDraft))if(Object.hasOwn(saved.draft,key))profileDraft[key]=saved.draft[key];profileStep=Math.max(1,Math.min(4,Number(saved.step)||1));}}catch{}
 for(const key of ['allergens','preferences'])if(!Array.isArray(profileDraft[key]))profileDraft[key]=[];
 if(typeof profileDraft.other_allergies!=='string')profileDraft.other_allergies='';
 // Corrupt or stale local state must not skip required steps.
 if(!validBasics())profileStep=1;else if(!validGoal()&&profileStep>2)profileStep=2;
}
function storeDraft(){try{localStorage.setItem(draftKey(),JSON.stringify({draft:profileDraft,step:profileStep}));}catch{}}
function validBasics(){profileDraft.age=ageFromBirth(profileDraft.birth_date);return ['male','female'].includes(profileDraft.sex)&&[[profileDraft.age,14,90,1],[profileDraft.weight,40,200,.5],[profileDraft.height,140,220,1]].every(([v,lo,hi,step])=>v!==null&&Number.isFinite(Number(v))&&Number(v)>=lo&&Number(v)<=hi&&Math.abs(Number(v)/step-Math.round(Number(v)/step))<1e-7);}
function validGoal(){return activityChoices.some(a=>a[0]===Number(profileDraft.activity))&&Object.hasOwn(goalLabels,profileDraft.goal);}
function navigate(destination,replace=false){
 if(!state)return renderAuth();
 page=flowPages.has(destination)?destination:'dashboard';
 if(!profileIsSaved())page='onboarding';else if(page==='onboarding')page='profile';
 if(page==='onboarding')prepareDraft();
 if(location.hash!=='#'+page)history[replace?'replaceState':'pushState'](null,'','#'+page);
 render();window.scrollTo(0,0);
}
window.addEventListener('popstate',()=>{if(state)navigate(location.hash.slice(1),true);});
window.addEventListener('hashchange',()=>{if(state)navigate(location.hash.slice(1),true);});
function decorateRegistration(){
 if(authMode!=='register')return;
 const form=document.querySelector('#auth-form');const row=document.createElement('div');row.className='field';row.innerHTML='<label for="name">Имя</label><input id="name" name="name" required maxlength="60" autocomplete="given-name" placeholder="Как к вам обращаться"><span class="field-error" data-error="name"></span>';form.prepend(row);
}
function flowHeader(){return `<header class="flow-header">${brand()}<div class="button-row">${profileIsSaved()&&page!=='dashboard'?'<button class="secondary" id="back-home">На главную</button>':''}<button class="link" id="flow-logout">Выйти</button></div></header>`;}
function bindFlowHeader(){
 mountGlobalLayout();
 const home=document.querySelector('#back-home');if(home)home.onclick=()=>navigate('dashboard');
 document.querySelector('#flow-logout').onclick=e=>busy(e.target,async()=>{await api('/auth/logout','POST',{});state=null;profileDraft=null;profileIdentity=null;history.replaceState(null,'',location.pathname);renderAuth();});
}
function slider(key,label,min,max,step,unit,fallback){const value=profileDraft[key],display=value===null?(key==='budget_week'?'Не указан':'Выберите'):`${num(value)} ${unit}`;return `<div class="range-field"><div class="range-heading"><label for="profile-${key}">${label}</label><output for="profile-${key}" id="value-${key}">${display}</output></div><input id="profile-${key}" data-range="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${value??fallback}" aria-describedby="range-${key}"><div class="range-ends" id="range-${key}"><span>${min} ${unit}</span><span>${max} ${unit}</span></div></div>`;}
function summaryBlock(title,step,rows){return `<section class="profile-summary-block"><div class="summary-block-head"><h3>${title}</h3><button class="link" data-edit-step="${step}">Изменить<span class="sr-only">: ${title}</span></button></div><dl>${rows.map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl></section>`;}
function renderOnboarding(){
 prepareDraft();const d=profileDraft;const titles=['Базовые параметры','Активность и цель','Ограничения','Проверьте профиль'];let content='';
 if(profileStep===1)content=`<fieldset class="sex-field"><legend>Пол</legend><div class="segmented">${[['male','М'],['female','Ж']].map(([v,label])=>`<label><input type="radio" name="sex" value="${v}" ${d.sex===v?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset>${birthField(d.birth_date)}${slider('weight','Вес',40,200,.5,'кг',80)}${slider('height','Рост',140,220,1,'см',175)}<p class="small muted" id="age-note">${d.age!==null&&d.age<18?'Автоматический рацион пока доступен с 18 лет.':''}</p>`;
 if(profileStep===2)content=`<fieldset class="choice-field"><legend>Активность</legend>${activityChoices.map(([v,title,sub])=>`<label class="choice-card"><input type="radio" name="activity" value="${v}" ${Number(d.activity)===v?'checked':''}><span><strong>${title}</strong><small>${sub}</small></span></label>`).join('')}</fieldset><fieldset class="choice-field"><legend>Цель</legend><div class="goal-options">${Object.entries(goalLabels).map(([v,label])=>`<label class="choice-card"><input type="radio" name="goal" value="${v}" ${d.goal===v?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset>`;
 if(profileStep===3)content=`<h3>Аллергии</h3><div class="check-grid">${state.allergens.map(a=>`<label class="check"><input type="checkbox" name="allergens" value="${esc(a)}" ${d.allergens.includes(a)?'checked':''}>${esc(a)}</label>`).join('')}<label class="check"><input id="has-other-allergy" type="checkbox" ${d.other_enabled?'checked':''}>Другое</label></div><div class="field other-allergy-field" id="other-allergy-field" ${d.other_enabled?'':'hidden'}><label for="other-allergies">Какие продукты исключить</label><input id="other-allergies" maxlength="200" value="${esc(d.other_allergies)}" placeholder="Например, яблоки"><p class="small muted">Незнакомые каталогу ограничения уточняются перед расчётом.</p></div><div class="separator"></div><h3>Предпочтения</h3><div class="check-grid">${Object.entries(preferenceLabels).map(([v,label])=>`<label class="check"><input type="checkbox" name="preferences" value="${v}" ${d.preferences.includes(v)?'checked':''}>${label}</label>`).join('')}</div><div class="separator"></div>${slider('budget_week','Бюджет на неделю',500,10000,100,'₽',3500)}<button class="link small" id="clear-budget" type="button">Не указывать бюджет</button>`;
 if(profileStep===4)content=`<div class="profile-review">${summaryBlock('Параметры',1,[['Имя',d.name],['Пол',d.sex==='male'?'Мужской':'Женский'],['Дата рождения',d.birth_date?dateLabel(d.birth_date+'T12:00:00'):'Не указана'],['Возраст',`${d.age} лет`],['Вес',`${num(d.weight)} кг`],['Рост',`${d.height} см`]])}${summaryBlock('Активность и цель',2,[['Активность',activityChoices.find(a=>a[0]===Number(d.activity))?.[1]],['Цель',goalLabels[d.goal]]])}${summaryBlock('Ограничения',3,[['Аллергии',d.allergens.join(', ')||'Не указаны'],['Другие',d.other_allergies||'Нет'],['Предпочтения',d.preferences.map(v=>preferenceLabels[v]).join(', ')||'Без ограничений'],['Бюджет на неделю',d.budget_week===null?'Не указан':money(d.budget_week*100)]])}</div>`;
 app.innerHTML=`${flowHeader()}<main class="onboarding"><div class="eyebrow">ВАШ ПРОФИЛЬ</div><h1>Настройте ваш профиль</h1><div class="step-meta"><span>Шаг ${profileStep} из 4</span><span>${titles[profileStep-1]}</span></div><div class="onboarding-progress" role="progressbar" aria-label="Заполнение профиля" aria-valuemin="1" aria-valuemax="4" aria-valuenow="${profileStep}">${[1,2,3,4].map(n=>`<span class="${n<=profileStep?'filled':''}"></span>`).join('')}</div><section class="panel onboarding-card"><h2>${titles[profileStep-1]}</h2><div id="page-error" class="error" role="alert"></div>${content}<div class="wizard-actions">${profileStep>1?'<button class="secondary" id="profile-prev">Назад</button>':'<span></span>'}<button id="profile-next" ${profileStep===1&&!validBasics()||profileStep===2&&!validGoal()?'disabled':''}>${profileStep===4?'Сохранить профиль':returnToSummary?'К сводке':'Далее'}</button></div></section></main>`;
 bindFlowHeader();const birth=document.querySelector('#profile-birth-date');if(birth)birth.oninput=()=>{d.birth_date=birth.value;d.age=ageFromBirth(birth.value);document.querySelector('#birth-age').textContent=d.age===null?'Укажите корректную дату':'Возраст: '+d.age+' лет';document.querySelector('#profile-next').disabled=!validBasics();document.querySelector('#age-note').textContent=d.age!==null&&d.age<18?'Автоматический рацион пока доступен с 18 лет.':'';storeDraft();};const prev=document.querySelector('#profile-prev');if(prev)prev.onclick=()=>{profileStep--;returnToSummary=false;storeDraft();renderOnboarding();};
 document.querySelector('#profile-next').onclick=e=>{if(profileStep===4)return busy(e.target,async()=>{state=await api('/profile','PUT',profileDraft);try{localStorage.removeItem(draftKey());}catch{}profileDraft=null;profileIdentity=null;returnToSummary=false;navigate('dashboard');toast('Профиль сохранён');});if(profileStep===1&&!validBasics()||profileStep===2&&!validGoal())return;profileStep=returnToSummary?4:profileStep+1;returnToSummary=false;storeDraft();renderOnboarding();window.scrollTo(0,0);};
 app.querySelectorAll('[data-range]').forEach(input=>input.oninput=()=>{const key=input.dataset.range;profileDraft[key]=Number(input.value);document.querySelector('#value-'+key).textContent=`${num(profileDraft[key])} ${key==='age'?'лет':key==='weight'?'кг':key==='height'?'см':'₽'}`;if(profileStep===1){document.querySelector('#profile-next').disabled=!validBasics();document.querySelector('#age-note').textContent=profileDraft.age!==null&&profileDraft.age<18?'Автоматический рацион пока доступен с 18 лет.':'';}storeDraft();});
 app.querySelectorAll('input[type=radio]').forEach(input=>input.onchange=()=>{profileDraft[input.name]=input.name==='activity'?Number(input.value):input.value;document.querySelector('#profile-next').disabled=profileStep===1?!validBasics():!validGoal();storeDraft();});
 app.querySelectorAll('input[name=allergens],input[name=preferences]').forEach(input=>input.onchange=()=>{profileDraft[input.name]=[...app.querySelectorAll(`input[name=${input.name}]:checked`)].map(i=>i.value);storeDraft();});
 const other=document.querySelector('#has-other-allergy');if(other)other.onchange=()=>{profileDraft.other_enabled=other.checked;storeDraft();document.querySelector('#other-allergy-field').hidden=!other.checked;if(!other.checked){profileDraft.other_allergies='';document.querySelector('#other-allergies').value='';storeDraft();}};
 const otherText=document.querySelector('#other-allergies');if(otherText)otherText.oninput=()=>{profileDraft.other_allergies=otherText.value;storeDraft();};
 const clear=document.querySelector('#clear-budget');if(clear)clear.onclick=()=>{profileDraft.budget_week=null;storeDraft();document.querySelector('#value-budget_week').textContent='Не указан';};
 app.querySelectorAll('[data-edit-step]').forEach(b=>b.onclick=()=>{profileStep=Number(b.dataset.editStep);returnToSummary=true;storeDraft();renderOnboarding();window.scrollTo(0,0);});
}
function renderDashboard(){const p=state.profile;app.innerHTML=`${flowHeader()}<main class="dashboard"><div class="eyebrow">МОЁ ПРОСТРАНСТВО</div><h1>Здравствуйте, ${esc(p.name)}!</h1><p class="muted">Ваш профиль готов. Можно настроить план питания.</p><section class="panel dashboard-profile"><div class="summary-block-head"><h2>Ваш профиль</h2><button class="link" id="edit-profile">Изменить</button></div><div class="dashboard-metrics"><div><span class="muted">Цель</span><strong>${goalLabels[p.goal]}</strong></div><div><span class="muted">Вес</span><strong>${num(p.weight)} кг</strong></div><div><span class="muted">Активность</span><strong>${activityChoices.find(a=>a[0]===Number(p.activity))?.[1]}</strong></div><div><span class="muted">Бюджет на неделю</span><strong>${p.budget_week===null?'Не указан':money(p.budget_week*100)}</strong></div></div></section><button class="plan-cta" id="configure-plan"><span>Настройте ваш план<small>Период, меню и стоимость корзины</small></span><span aria-hidden="true">→</span></button><section class="future-features"><span aria-hidden="true">＋</span><p>Здесь появятся другие функции</p></section></main>`;bindFlowHeader();document.querySelector('#edit-profile').onclick=()=>{profileIdentity=null;returnToSummary=false;navigate('profile');};document.querySelector('#configure-plan').onclick=()=>navigate('settings');}
function renderPlanForm(el){const p=state.profile,last=state.plan?.settings||{},days=last.days||7;el.innerHTML=`<div class="button-row plan-back"><button class="link" id="plan-back">← На главную</button><button class="link" id="plan-edit-profile">Изменить профиль</button></div><div class="note">${esc(p.name)} · ${goalLabels[p.goal]} · ${num(p.weight)} кг. Параметры берём из сохранённого профиля.</div><form id="plan-form" class="panel"><h2>Настройте ваш план</h2><div class="form-grid">${field('days','Период, дней',days,'number','min="7" max="31"')}${field('start_date','Начало плана',last.start_date||new Date().toLocaleDateString('en-CA'),'date')}${select('meals','Приёмов пищи в день',last.meals||3,[[3,'3'],[4,'4'],[5,'5']])}${field('minutes','Готовка, не более минут',last.minutes||30,'number','min="5" max="180"')}${field('budget','Бюджет на весь план, ₽',last.budget??Math.round((p.budget_week||3500)*days/7),'number','min="1" max="1000000" step="0.01"')}${field('repeat','Повторов блюда за неделю',last.repeat||2,'number','min="1" max="7"')}</div><div class="separator"></div><h3>Предпочтения для этого плана</h3><div class="check-grid">${Object.entries(preferenceLabels).map(([v,label])=>`<label class="check"><input type="checkbox" name="preferences" value="${v}" ${(last.preferences||p.preferences||[]).includes(v)?'checked':''}>${label}</label>`).join('')}</div><div class="wizard-actions"><span class="small muted">Аллергии из профиля сохраняются.</span><button type="submit">Составить меню</button></div></form><section id="plan-results"></section>`;document.querySelector('#plan-back').onclick=()=>navigate('dashboard');document.querySelector('#plan-edit-profile').onclick=()=>{profileIdentity=null;navigate('profile');};let budgetEdited=last.budget!==undefined&&Math.abs(last.budget-Math.round((p.budget_week||3500)*days/7))>.01;document.querySelector('#budget').oninput=()=>{budgetEdited=true;};document.querySelector('#days').oninput=e=>{if(!budgetEdited&&e.target.validity.valid)document.querySelector('#budget').value=Math.round((p.budget_week||3500)*Number(e.target.value)/7);};document.querySelector('#plan-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),options=Object.fromEntries(f);options.preferences=f.getAll('preferences');busy(e.submitter,async()=>{state=await api('/plan','POST',options);selectedDay=0;navigate('result');toast('Меню и корзина рассчитаны');});};if(state.plan){const link=document.createElement('button');link.className='link';link.id='back-to-result';link.textContent='К текущему результату';link.onclick=()=>navigate('result');el.append(link);}}
